head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top_1);
        $c.cm.PanelToGroupBox(panel_Top_2);
        $c.cm.PanelToGroupBox(panel_Top_3);
        $c.cm.PanelToGroupBox(panel_Top_4);
        $c.cm.PanelToGroupBox(panel_Top_5);
        MaxTab_01.setSelectedTabIndex(1);

        // 장내청산결제운영팀
        if (js_dep_cd === "4B30") {
            chb_STK_FUT_OPT_YN.setDisabled(true);
            chb_STK_FUT_OPT_YN.setValue('Y');
        }
        if (js_market === "1" || js_market === "2" || js_market === "6") {
            $c.cm.setColumnProp(grd_List_1, "TR_MKT_NM", "Show", false);
            $c.cm.setColumnProp(grd_List_2, "TR_MKT_NM", "Show", false);
            $c.cm.setColumnProp(grd_List_4, "TR_MKT_NM", "Show", false);
            rdo_MARKET_TP_CD_1.setValue(js_market);
            rdo_MARKET_TP_CD_2.setValue(js_market);
            rdo_MARKET_TP_CD_4.setValue(js_market);
        }
        if (js_market === "1" || js_market === "2" || js_market === "6") {
            panel_mkt_gubun_1.hide();
            panel_mkt_gubun_2.hide();
            panel_mkt_gubun_4.hide();
        } else {
            panel_mkt_gubun_1.show("");
            panel_mkt_gubun_2.show("");
            panel_mkt_gubun_4.show("");
        }
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_SDate_1.setValue($c.ut.cGetMinusDate2(vCurDate, 7));
        edt_SDate_2.setValue($c.ut.cGetMinusDate2(vCurDate, 7));
        edt_SDate_3.setValue($c.ut.cGetMinusDate2(vCurDate, 365));
        edt_SDate_4.setValue($c.ut.cGetMinusDate2(vCurDate, 365));
        edt_SDate_5.setValue($c.ut.cGetMinusDate2(vCurDate, 7));
        edt_EDate_1.setValue(vCurDate); // 현재날짜
        edt_EDate_2.setValue(vCurDate); // 현재날짜
        edt_EDate_3.setValue(vCurDate); // 현재날짜
        edt_EDate_4.setValue(vCurDate); // 현재날짜
        edt_EDate_5.setValue(vCurDate); // 현재날짜

        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_1);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_2);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_3);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_4);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_5);
        await scwin.setComboCode();
        await scwin.listSync1();
        $c.cm.fn_com_isur(txb_ISUR_CD_1, txb_COM_NM_1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20700.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rdo_MARKET_TP_CD_1_onclick
 * @description rdo_MARKET_TP_CD_1 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rdo_MARKET_TP_CD_1_onclick = async function() {
    try {
        await scwin.setComboCode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20700.rdo_MARKET_TP_CD_1_onclick" });
    }
};

/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
        let Rows;
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            Rows = dts_List_1.getRowCount();
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            Rows = dts_List_2.getRowCount();
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            Rows = dts_List_3.getRowCount();
        } else if (MaxTab_01.getSelectedTabIndex() === 4) {
            Rows = dts_List_4.getRowCount();
        } else if (MaxTab_01.getSelectedTabIndex() === 5) {
            Rows = dts_List_5.getRowCount();
        }
        $c.stf.fillGridHeaderTotalCnt(Rows, panel_page);
        // fn_list_sync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF20700.MaxTab_01_OnSelChanged" });
    }
};

