 */
scwin.dts_STK_ISU_RSN_CD_OnLoadCompleted = function(rowcount) {
    try {
        dts_STK_ISU_RSN_CD.insertRow(0);
        dts_STK_ISU_RSN_CD.setCellData(1, "VALUE", "");
        dts_STK_ISU_RSN_CD.setCellData(1, "TEXT", "전체");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF20700.dts_STK_ISU_RSN_CD_OnLoadCompleted" });
    }
};

