    url += "?SCREN_ID=" + "ULDSTF20700.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=STK_ISU_RSN_CD_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.stkissrsncd.select.condition" + "&{P}param01=" + rdo_MARKET_TP_CD_1.getValue() + "&{P}param02=" + rdo_MARKET_TP_CD_1.getValue() + "&{P}param03=" + rdo_MARKET_TP_CD_1.getValue();
    const sbmOptions = {
        id : "sbm_dts_STK_ISU_RSN_CD",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_STK_ISU_RSN_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

